package glitch

import data.glitch_lib

# Insecure protocols that indicate cleartext transmission
insecure_protocols := {"http://", "ftp://", "telnet://", "smtp://", "http", "ftp", "telnet", "smtp"}

# Encryption-related attribute names
encryption_attrs := {"encryption", "tls", "ssl", "encrypted", "in_transit_encryption", "encryption_in_transit", "https_only", "secure_transport", "enforce_tls", "require_ssl", "minimum_tls_version", "min_tls_version", "ssl_policy", "tls_policy", "tls_mode", "ssl_mode", "certificate", "certificate_arn", "default_certificate", "tls_certificate"}

# Insecure encryption values
insecure_encryption_values := {"disabled", "false", "none", "optional", "disable", "off", "no", "0"}

# Insecure TLS versions
insecure_tls_versions := {"1.0", "1.1", "tls_1_0", "tls_1_1", "sslv3", "sslv2", "ssl3", "ssl2"}

# Unencrypted default ports
unencrypted_ports := {80, 21, 23, 25, 110, 143, 587, 8080}

# Port attributes to check
port_attrs := {"port", "from_port", "to_port", "container_port", "host_port"}

# Checks if a value contains insecure protocol
has_insecure_protocol(value) {
    value.ir_type == "String"
    lower := lower(value.value)
    startswith(lower, insecure_protocols[_])
}

has_insecure_protocol(value) {
    value.ir_type == "String"
    lower := lower(value.value)
    lower == insecure_protocols[_]
}

# Check for insecure encryption configuration
is_insecure_encryption_config(attr) {
    encryption_attrs[lower(attr.name)]
    check_insecure_value(attr.value)
}

check_insecure_value(value) {
    value.ir_type == "String"
    lower := lower(value.value)
    insecure_encryption_values[lower]
}

check_insecure_value(value) {
    value.ir_type == "Boolean"
    value.value == false
}

check_insecure_value(value) {
    value.ir_type == "String"
    lower := lower(value.value)
    insecure_tls_versions[lower]
}

# Check for missing TLS with sensitive protocol usage
is_sensitive_protocol_without_tls(node) {
    attrs := glitch_lib.all_attributes(node)
    protocol_attr := attrs[_]
    contains(lower(protocol_attr.name), "protocol")
    protocol_attr.value.ir_type == "String"
    proto := lower(protocol_attr.value.value)
    proto == insecure_protocols[_]
    not has_tls_config(attrs)
}

has_tls_config(attrs) {
    attr := attrs[_]
    encryption_attrs[lower(attr.name)]
    not check_insecure_value(attr.value)
}

# Check for unencrypted port usage
has_unencrypted_port(attrs) {
    attr := attrs[_]
    port_attrs[lower(attr.name)]
    is_insecure_port_value(attr.value)
}

is_insecure_port_value(value) {
    value.ir_type == "Integer"
    unencrypted_ports[value.value]
}

is_insecure_port_value(value) {
    value.ir_type == "String"
    port_num := to_number(value.value)
    unencrypted_ports[port_num]
}

# Check connection strings with disabled encryption
has_insecure_connection_string(value) {
    value.ir_type == "String"
    conn := lower(value.value)
    contains(conn, "encrypt=false")
} else {
    value.ir_type == "String"
    conn := lower(value.value)
    contains(conn, "sslmode=disable")
} else {
    value.ir_type == "String"
    conn := lower(value.value)
    contains(conn, "tls=false")
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for insecure encryption attribute values
    is_insecure_encryption_config(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Encryption for data transmission is disabled or set to insecure values. (CWE-319)"
    }
}

